(()=>{'use strict';
const C=window.RAAHI_CONFIG||{},$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>'₹'+Number(n||0).toLocaleString('en-IN');
const portal=location.pathname.includes('rider')?'captain':location.pathname.includes('user')?'customer':'admin';
let tab=portal==='customer'?'Book a ride':portal==='captain'?'My workspace':'Overview',filter='All rides',search='',mode='bike',live=localStorage.getItem('raahi.mode')==='live',session=JSON.parse(sessionStorage.getItem('raahi.session')||'null'),profile=null,rides=[],captains=[],audits=[],busy=false;
const uid=()=>{const b=new Uint8Array(16);crypto.getRandomValues(b);b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const h=[...b].map(x=>x.toString(16).padStart(2,'0')).join('');return h.slice(0,8)+'-'+h.slice(8,12)+'-'+h.slice(12,16)+'-'+h.slice(16,20)+'-'+h.slice(20)},now=()=>new Date().toISOString();
function seed(){return {rides:[{id:'demo-1004',pickup:'FC Road, Deccan',destination:'Koregaon Park',mode:'bike',fare:89,distance_km:6.8,status:'in_progress',customer_id:'customer-2',captain_id:'captain-2',created_at:now()},{id:'demo-1003',pickup:'Baner Road',destination:'Shivajinagar',mode:'auto',fare:142,distance_km:8.2,status:'requested',customer_id:'customer-3',created_at:now()},{id:'demo-1002',pickup:'Pune Railway Station',destination:'Viman Nagar',mode:'cab',fare:268,distance_km:10.9,status:'completed',customer_id:'customer-4',captain_id:'captain-2',created_at:now()},{id:'demo-1001',pickup:'Aundh',destination:'University Road',mode:'bike',fare:64,distance_km:4.2,status:'completed',customer_id:'customer-5',captain_id:'captain-demo',created_at:now()}],captains:[{id:'captain-demo',name:'Arjun Deshmukh',vehicle:'MH 12 AB 4821 · Bike',approved:true,online:true},{id:'captain-2',name:'Vikram Patil',vehicle:'MH 12 KL 9041 · Bike',approved:true,online:true},{id:'captain-3',name:'Sahil Khan',vehicle:'MH 14 GH 2210 · Auto',approved:false,online:false},{id:'captain-4',name:'Priya Sharma',vehicle:'MH 12 CD 7088 · Bike',approved:false,online:false},{id:'captain-5',name:'Rohit Jadhav',vehicle:'MH 12 EF 5562 · Cab',approved:false,online:false}],audit:[],dismissed:[]}}
let demo;try{demo=JSON.parse(localStorage.getItem('raahi.demo'))||seed()}catch{demo=seed()}
function save(){localStorage.setItem('raahi.demo',JSON.stringify(demo))}
function log(action,entity,detail=''){demo.audit.unshift({action,entity,detail,created_at:now()});save()}
function toast(s){$('#toast').textContent=s;$('#toast').classList.remove('hide');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.add('hide'),5000)}
function token(){return session?.access_token||''}
let refreshing;
async function ensureSession(){if(!session?.refresh_token||Number(session.expires_at||0)>Date.now()/1000+60)return;if(!refreshing)refreshing=(async()=>{const r=await fetch(C.supabaseUrl+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:C.supabaseAnonKey,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})});const data=await r.json();if(!r.ok)throw Error('Session expired. Please sign in again.');session=data;sessionStorage.setItem('raahi.session',JSON.stringify(data))})().finally(()=>refreshing=null);await refreshing}
async function api(path,data){await ensureSession();const res=await fetch((C.apiBase||'')+'/v1/'+path,{method:data?'POST':'GET',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token()},body:data?JSON.stringify(data):undefined});let out;try{out=await res.json()}catch{throw Error('Go API is not available at this address. Deploy the backend and set its API URL in the connection configuration.')}if(!res.ok)throw Error(out.message||out.error||'Request failed');return out}
async function load(){if(!live){rides=demo.rides;captains=demo.captains;audits=demo.audit;profile={id:portal==='captain'?'captain-demo':'customer-demo',name:portal==='admin'?'Aditi Kulkarni':portal==='captain'?'Arjun Deshmukh':'Ananya',role:portal,approved:true};return}if(!session){rides=[];captains=[];audits=[];profile=null;return}const result=await Promise.all([api('profile'),api('rides'),portal==='admin'?api('captains'):Promise.resolve([]),portal==='admin'?api('audit'):Promise.resolve([])]);profile=result[0].find(x=>x.id===session.user.id)||null;rides=result[1];captains=result[2];audits=result[3];if(profile&&profile.role!==portal)throw Error('This account belongs to the '+profile.role+' portal. Use the matching panel.')}
const navs=portal==='admin'?[['Overview','◫'],['Rides','⇄'],['Captains','♧'],['Analytics','▥'],['Safety centre','⊕'],['Settings','⚙']]:portal==='captain'?[['My workspace','◫'],['My rides','⇄'],['Earnings','▥'],['Safety centre','⊕'],['Settings','⚙']]:[['Book a ride','⌖'],['My rides','⇄'],['Safety centre','⊕'],['Settings','⚙']];
function stat(title,value,note,icon){return `<div class="stat"><div class="stathead">${title}<i>${icon}</i></div><strong>${value}</strong><small>${note}</small></div>`}
function status(s){return `<span class="tag ${esc(s)}">${esc(s.replaceAll('_',' '))}</span>`}
function mainMap(){return `<div class="card"><div class="cardhead"><div><h2>${portal==='admin'?'Live operations':'Your city, connected'}</h2><p class="sub" style="margin-top:6px">Pune, Maharashtra <span style="margin:0 7px">·</span> ${live?'Location overview':'Illustrative dispatch view'}</p></div><button class="pill" data-action="map">↗ Open map</button></div><div class="map" id="citymap"><img src="map.svg" alt="Illustrative Pune dispatch map, not live GPS" style="width:100%;height:100%;object-fit:cover"><div class="mapbadge"><span class="dot"></span>${live?'Map overview · no live GPS overlay':'Simulation · Pune central'}</div><div class="maplegend"><span><i class="legendline"></i>Captain</span><span>● Pickup</span><span>◌ Destination</span></div><div class="maptools"><button data-action="map" aria-label="Open street map">⌖</button></div></div><div class="mapfoot"><span>© OpenStreetMap contributors in street map view</span><span>${live?'Refresh every 5s':'Demo coordinates'}</span></div></div>`}
function approvalCard(all=false){const pending=captains.filter(c=>!c.approved);return `<div class="card"><div class="cardhead"><div><h2>Captain approvals <span class="tag" style="margin-left:5px">${pending.length}</span></h2><p class="sub" style="margin-top:6px">Review before they hit the road</p></div><span>⋯</span></div><div class="list">${(all?captains:pending.slice(0,3)).map(c=>`<div class="approval"><div class="row"><div class="person"><div class="avatar">${esc(c.name.split(' ').map(x=>x[0]).join(''))}</div><div><b>${esc(c.name)}</b><small>${esc(c.vehicle||'Vehicle details pending')}</small></div></div>${c.approved?status('accepted'):''}</div><div class="actions"><button class="btn light" data-action="review" data-id="${esc(c.id)}">View details</button>${!c.approved?`<button class="btn" data-action="approve" data-id="${esc(c.id)}">✓ Approve</button><button class="btn danger" data-action="rejectCaptain" data-id="${esc(c.id)}" aria-label="Reject ${esc(c.name)}">✕</button>`:`<button class="btn danger" data-action="rejectCaptain" data-id="${esc(c.id)}">Suspend</button>`}</div></div>`).join('')||'<div class="empty">No applications awaiting review.</div>'}</div>${!all?'<button class="viewall" data-tab="Captains">View all captains →</button>':''}</div>`}
function visibleRides(){return rides.filter(r=>portal==='admin'||(portal==='captain'?(r.captain_id===profile?.id||(r.status==='requested'&&!demo.dismissed.includes(r.id))):r.customer_id===profile?.id))}
function table(){const rows=visibleRides().filter(r=>(filter==='All rides'||(filter==='Active'? !['completed','cancelled'].includes(r.status):r.status===filter.toLowerCase()))&&[r.id,r.pickup,r.destination].join(' ').toLowerCase().includes(search.toLowerCase()));return `<div class="card tablecard"><div class="cardhead"><div><h2>${portal==='admin'?'Ride activity':'Your rides'}</h2><p class="sub" style="margin-top:6px">Every journey, in one place.</p></div><input class="search" id="search" placeholder="Search rides…" aria-label="Search rides" value="${esc(search)}"></div><div class="tabs">${['All rides','Active','Completed','Cancelled'].map(x=>`<button data-filter="${x}" class="${filter===x?'active':''}">${x}</button>`).join('')}</div><div class="tablewrap"><table><thead><tr><th>RIDE ID</th><th>ROUTE</th><th>SERVICE</th><th>FARE</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>#${esc(r.id.slice(-8).toUpperCase())}</b><small>${new Date(r.created_at).toLocaleDateString('en-IN',{day:'2-digit',month:'short'})}</small></td><td class="route">● ${esc(r.pickup)}<small>↳ ${esc(r.destination)}</small></td><td>${esc(r.mode.charAt(0).toUpperCase()+r.mode.slice(1))}</td><td><b>${money(r.fare)}</b><small>${esc(r.distance_km)} km · cash</small></td><td>${status(r.status)}</td><td><button class="btn light" style="padding:6px 10px;font-size:10px" data-action="trip" data-id="${esc(r.id)}">View →</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No rides here yet.</td></tr>'}</tbody></table></div><div class="tablefoot"><span>Showing ${rows.length} rides · ${live?'latest 100 records':'simulation data'}</span><span>Updated just now ↻</span></div></div>`}
function overview(){const active=rides.filter(r=>!['completed','cancelled'].includes(r.status));return `<div class="stats">${stat('Total rides',rides.length,'In the current activity window','⇄')}${stat('Active captains',captains.filter(c=>c.approved&&c.online).length,'Approved & available','♧')}${stat('Completed fares',money(rides.filter(r=>r.status==='completed').reduce((n,r)=>n+r.fare,0)),'Gross fares · not platform revenue','↗')}${stat('Ongoing rides',active.length,'Across all service types','⌖')}</div><div class="board">${mainMap()}${approvalCard()}</div>${table()}`}
function booking(){return `<div class="board"><div class="card"><div class="cardhead"><div><div class="eyebrow">GOOD TO SEE YOU</div><h2 style="font-size:23px;margin-top:8px">Where are we headed?</h2></div><span class="tag">Pune</span></div><form class="form" id="booking"><label for="pickup">PICKUP</label><select id="pickup" name="pickup"><option value="deccan">FC Road, Deccan</option><option value="baner">Baner Road</option><option value="station">Pune Railway Station</option><option value="aundh">Aundh</option></select><label for="drop">DESTINATION</label><select id="drop" name="drop"><option value="kp">Koregaon Park</option><option value="viman">Viman Nagar</option><option value="shivaji">Shivajinagar</option><option value="camp">MG Road, Camp</option></select><div class="modes">${[['bike','♧','Bike','From ₹20 + ₹8/km'],['auto','♜','Auto','From ₹35 + ₹13/km'],['cab','▱','Cab','From ₹60 + ₹19/km']].map(([id,icon,label,price])=>`<button type="button" class="mode ${mode===id?'active':''}" data-mode="${id}"><span>${icon}</span><b>${label}</b><small>${price}</small></button>`).join('')}</div><div class="notice">${live?'Fare uses a distance estimate, not a road routing quote.':'Try a connected journey: book here, then open the Captain panel to accept it.'} <br>Pay the captain in cash after your ride.</div><button class="btn" type="submit" style="width:100%;margin-top:20px">Find a captain <span>→</span></button><p class="fineprint">Distance uses a 1.3 × straight-line estimate. Bike, auto and cab availability depends on local operations.</p></form></div>${mainMap()}</div>${table()}`}
function captain(){const me=live?profile:captains.find(c=>c.id==='captain-demo');return `<div class="stats">${stat('Your status',me?.approved?(me.online?'Online':'Offline'):'Pending','Admin approval required for dispatch','●')}${stat('Completed rides',rides.filter(r=>r.captain_id===profile?.id&&r.status==='completed').length,'In the current activity window','⇄')}${stat('Gross fares',money(rides.filter(r=>r.captain_id===profile?.id&&r.status==='completed').reduce((n,r)=>n+r.fare,0)),'Cash collected · before fees','↗')}${stat('Available requests',rides.filter(r=>r.status==='requested'&&!demo.dismissed.includes(r.id)).length,'Accept one ride at a time','⌖')}</div><div class="board">${mainMap()}<div class="card"><div class="cardhead"><h2>Ready for your next ride?</h2></div><div class="form"><p class="sub">${esc(me?.name||'Sign in to your captain account')}</p><p>Go online to see requests. Confirm arrival, verify the customer’s start code, and complete the trip.</p><button class="btn" data-action="online">${me?.online?'Go offline':'Go online'}</button><button class="btn light" style="margin-left:8px" data-action="location">Share position</button><p class="fineprint">${live?'Real vehicle verification must be completed by your operations team.':'Simulation account is already approved.'}</p></div></div></div>${table()}`}
function analytics(){const completed=visibleRides().filter(r=>r.status==='completed'),modes=['bike','auto','cab'];return `<div class="stats">${stat('Completed',completed.length,'Completed journeys','✓')}${stat('Gross fares',money(completed.reduce((n,r)=>n+r.fare,0)),'Cash collection, not settled payouts','↗')}${stat('Cancelled',visibleRides().filter(r=>r.status==='cancelled').length,'Cancelled journeys','✕')}${stat('Average fare',money(completed.length?Math.round(completed.reduce((n,r)=>n+r.fare,0)/completed.length):0),'Across completed journeys','▥')}</div><div class="card"><div class="cardhead"><h2>Completed rides by service</h2><span class="tag">Current data</span></div><div class="chart">${modes.map(m=>`<div class="bar" style="height:${Math.max(5,completed.filter(r=>r.mode===m).length/Math.max(1,completed.length)*130)}px"><small>${m} · ${completed.filter(r=>r.mode===m).length}</small></div>`).join('')}</div></div>${table()}`}
function safety(){return `<div class="board"><div class="card form"><div class="eyebrow">SAFETY CENTRE</div><h2 style="font-size:24px;margin-top:10px">Every journey deserves care.</h2><p>Trip start codes and restricted account access are built into the ride flow.</p><div class="notice">The SOS action records an alert for operations. This build does not contact emergency services, send SMS, or provide a monitored response centre.</div><p>Use your phone’s emergency calling feature for immediate help.</p></div><div class="card form"><h2>Operations log</h2>${audits.slice(0,15).map(a=>`<div class="approval"><b>${esc(a.action)}</b><p class="sub">${esc(a.detail||a.entity||'')} · ${new Date(a.created_at).toLocaleTimeString('en-IN')}</p></div>`).join('')||'<p class="sub" style="margin-top:15px">No accessible events. Admin accounts can review audit records.</p>'}</div></div>`}
function settings(){return `<div class="board"><div class="card form"><h2>Connected environment</h2><p class="sub">The web panels and Android apps use one Go API.</p><p><span class="tag">${live?'Live mode':'Simulation mode'}</span></p><p class="fineprint">API: ${esc(C.apiBase||'same origin')}<br>Database: ${C.supabaseUrl?'Configured':'Not configured'}</p><button class="btn" data-action="switch">Switch to ${live?'simulation':'live'} mode</button> <button class="btn light" data-action="login">${session?'Account':'Sign in'}</button><p class="fineprint">Live mode requires a deployed Go API, the SQL migration and Supabase Auth configuration. Edit config.js before deployment. Never put service-role secrets in browser code.</p></div><div class="card form"><h2>Your ecosystem</h2><p>Open a dedicated workspace.</p><div class="actions"><a class="btn light" href="admin.html">Management ↗</a><a class="btn light" href="rider.html">Captain ↗</a><a class="btn light" href="user.html">Customer ↗</a></div><p class="fineprint">Demo changes are shared between tabs on this browser. Live changes are saved in your database.</p><button class="btn danger" data-action="reset">Reset simulation data</button></div></div>`}
function render(){const titles={'Overview':['Operations overview','A clear view of your city. Every ride, every captain.'],'Book a ride':['A little closer to anywhere.','Everyday rides. Fair fares. Your city, made simple.'],'My workspace':['Let’s get you moving.','Your next opportunity is just around the corner.'],'Rides':['Ride management','Follow every journey from request to arrival.'],'My rides':['Your journeys','All your rides, together.'],'Captains':['Captain management','Review applications and manage availability.'],'Analytics':['Performance overview','Understand your mobility network.'],'Earnings':['Your earnings','Track completed cash fares.'],'Safety centre':['Safety centre','Support built around the journey.'],'Settings':['Workspace settings','One ecosystem. Connected workspaces.']};const [title,subtitle]=titles[tab]||titles.Overview;const body=tab==='Overview'?overview():tab==='Book a ride'?booking():tab==='My workspace'?captain():['Rides','My rides'].includes(tab)?table():tab==='Captains'?approvalCard(true):['Analytics','Earnings'].includes(tab)?analytics():tab==='Safety centre'?safety():settings();$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="logo" href="index.html"><i>↗</i>raahi<span style="font-size:14px;color:#93a18e;letter-spacing:0">®</span></a><div class="workspace"><span class="square">◫</span><div><strong>${portal==='admin'?'Mobility workspace':portal==='captain'?'Captain workspace':'Your city companion'}</strong><small>${portal==='admin'?'Operations & management':portal==='captain'?'Drive. Earn. Repeat.':'Move your way.'}</small></div></div><div class="navlabel">WORKSPACE</div><nav class="nav">${navs.map(([n,i])=>`<button data-tab="${n}" class="${tab===n?'active':''}"><span>${i}</span>${n}${n==='Captains'?'<span class="tag" style="font-size:9px;margin-left:auto">'+captains.filter(c=>!c.approved).length+'</span>':''}</button>`).join('')}</nav><footer><div class="platform"><b><em></em>${live?'API connected mode':'Explore the ecosystem'}</b>${live?'Your operational workspace.':'Three workspaces. One journey.'}<div class="portalnav"><a href="user.html">Customer ↗</a><a href="rider.html">Captain ↗</a></div></div><div class="profile"><div class="avatar">${portal==='admin'?'AK':portal==='captain'?'AD':'AN'}</div><div><b style="font-size:11px">${esc(profile?.name||'Guest account')}</b><small>${portal==='admin'?'Workspace administrator':portal==='captain'?'Captain partner':'Customer'}</small></div><button data-action="login" aria-label="Account settings" style="margin-left:auto;background:transparent">⋮</button></div></footer></aside><main class="main"><header class="topbar"><div class="breadcrumb">Workspace <span style="padding:0 13px">/</span> <b>${esc(tab)}</b></div><div class="topright"><span class="pill optional">⌖ Pune, India⌄</span><span class="pill"><i class="dot"></i>${live?'Live environment':'Demo workspace'}</span><button class="pill" data-action="login" aria-label="Sign in">${session?'Account':'Sign in'} ↗</button></div></header><div class="content"><div class="heading"><div><h1>${title}</h1><p class="sub">${subtitle}</p></div><button class="btn light" data-action="export">↓ Export rides</button></div>${!live?'<div class="banner"><span>✧ <b>Simulation workspace.</b> Explore the full ride flow with sample data. No real rides or payments.</span><button data-tab="Settings">Connect live API ↗</button></div>':!session?'<div class="banner"><span>Sign in to access your live workspace.</span><button data-action="login">Sign in →</button></div>':''}${body}<p class="statusbar" style="margin-top:25px">RAAHI MOBILITY OS <span style="float:right">Built for the road ahead. ↗</span></p></div></main></div>`}
function modal(content){$('#overlay').innerHTML=`<div class="modalback"><div class="modal" role="dialog" aria-modal="true"><button class="close" data-action="close" aria-label="Close dialog">✕</button>${content}</div></div>`;$('#overlay').querySelector('input,button')?.focus()}
function close(){$('#overlay').innerHTML=''}
function tripModal(id){const r=rides.find(x=>x.id===id);if(!r)return;let buttons='';if(portal==='captain'){if(r.status==='requested')buttons=`<button class="btn" data-action="accept" data-id="${esc(id)}">Accept ride</button><button class="btn danger" data-action="reject" data-id="${esc(id)}">Reject</button>`;else if(r.captain_id===profile?.id){const action={accepted:['arrive','I have arrived'],arrived:['start','Verify code & start'],in_progress:['complete','Complete ride']}[r.status];if(action)buttons=`<button class="btn" data-action="${action[0]}" data-id="${esc(id)}">${action[1]}</button>`}}if((portal==='admin'||r.customer_id===profile?.id||r.captain_id===profile?.id)&&['requested','accepted','arrived'].includes(r.status))buttons+=`<button class="btn danger" data-action="cancel" data-id="${esc(id)}">Cancel ride</button>`;modal(`<div class="eyebrow">JOURNEY #${esc(id.slice(-8))}</div><h2 style="margin-top:12px">${esc(r.pickup)} → ${esc(r.destination)}</h2><p>${status(r.status)} <b style="float:right">${money(r.fare)}</b></p><p class="sub">${esc(r.distance_km)} km · ${esc(r.mode)} · cash payment</p>${r.customer_id===profile?.id&&!['completed','cancelled'].includes(r.status)?`<div class="notice" style="margin-top:15px">Start code: <b id="startcode">${live?'Loading…':esc(r.code||'4826')}</b><br>Share only after your captain arrives.</div>`:''}${r.status==='arrived'&&portal==='captain'?'<label for="tripcode">Customer start code</label><input id="tripcode" inputmode="numeric" maxlength="4" placeholder="4-digit code">':''}<div class="actions">${buttons}</div>${['accepted','arrived','in_progress'].includes(r.status)&&portal!=='admin'?`<button class="btn light" style="margin-top:18px" data-action="track" data-id="${esc(id)}">Captain position</button> <button class="btn danger" style="margin-top:18px" data-action="sos" data-id="${esc(id)}">Record SOS alert</button>`:''}<p class="fineprint">${live?'Fare is an estimate based on coordinates.':'Simulated journey. No real captain or payment.'}</p>`);if(live&&r.customer_id===profile?.id&&$('#startcode'))api('code',{p_ride_id:id}).then(code=>{if($('#startcode'))$('#startcode').textContent=code}).catch(e=>toast(e.message))}
const places={deccan:['FC Road, Deccan',18.5196,73.8413],baner:['Baner Road',18.559,73.7868],station:['Pune Railway Station',18.5285,73.8742],aundh:['Aundh',18.559,73.8078],kp:['Koregaon Park',18.5362,73.894],viman:['Viman Nagar',18.5679,73.9143],shivaji:['Shivajinagar',18.5314,73.8446],camp:['MG Road, Camp',18.513,73.879]};
function estimate(a,b){const rad=n=>n*Math.PI/180;return Math.round(6371*2*Math.asin(Math.sqrt(Math.sin(rad(b[1]-a[1])/2)**2+Math.cos(rad(a[1]))*Math.cos(rad(b[1]))*Math.sin(rad(b[2]-a[2])/2)**2))*1.3*100)/100}
async function transition(id,action){if(live){await api('transition',{p_ride_id:id,p_action:action,p_code:$('#tripcode')?.value||''})}else{const r=demo.rides.find(x=>x.id===id),me=demo.captains[0];if(!r)throw Error('Ride not found');if(action==='reject'){demo.dismissed.push(id)}else if(action==='accept'){if(!me.approved||!me.online)throw Error('Go online with an approved account first');if(r.status!=='requested'||demo.rides.some(x=>x.captain_id===me.id&&!['completed','cancelled'].includes(x.status)))throw Error('Finish your current ride first');r.captain_id=me.id;r.status='accepted'}else{const transitions={arrive:['accepted','arrived'],start:['arrived','in_progress'],complete:['in_progress','completed']};if(action==='cancel'){if(!['requested','accepted','arrived'].includes(r.status))throw Error('This ride cannot be cancelled');r.status='cancelled'}else{if(r.captain_id!==me.id||r.status!==transitions[action]?.[0])throw Error('Invalid ride transition');if(action==='start'&&$('#tripcode')?.value!==(r.code||'4826'))throw Error('Incorrect start code');r.status=transitions[action][1]}}log('ride.'+action,id)}close();await load();render();toast('Ride '+action+' recorded')}
async function act(action,id){if(action==='close')return close();if(action==='trip')return tripModal(id);if(action==='login'){return modal(`<h2>${session?'Your account':'Connect your account'}</h2><p class="sub">${live?'Live environment':'Switch to live mode in Settings to use an account.'}</p><form id="auth" class="form"><label>Email</label><input type="email" name="email" required autocomplete="email"><label>Password</label><input type="password" name="password" minlength="8" required autocomplete="current-password"><label>Name (for registration)</label><input name="name" placeholder="Your full name"><div class="actions"><button class="btn" name="intent" value="login">Sign in</button>${portal!=='admin'?'<button class="btn light" name="intent" value="signup">Create account</button>':''}</div></form>${session?'<button class="btn danger" style="margin-top:16px" data-action="logout">Sign out</button>':''}<p class="fineprint">Admin access is granted by the database owner. Customer and captain accounts use separate portals.</p>`)}if(action==='logout'){session=null;sessionStorage.removeItem('raahi.session');close();await load();render();return}if(action==='switch'){live=!live;localStorage.setItem('raahi.mode',live?'live':'demo');await load();render();return}if(action==='reset'){if(!confirm('Reset all simulated rides and captains?'))return;demo=seed();save();await load();render();return}if(action==='map'){$('#citymap').innerHTML='<iframe title="Pune OpenStreetMap" style="border:0;width:100%;height:100%" src="https://www.openstreetmap.org/export/embed.html?bbox=73.76%2C18.48%2C73.96%2C18.60&layer=mapnik" loading="lazy"></iframe>';return}if(action==='export'){const safe=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const csv=[['id','pickup','destination','service','fare_inr','status'],...visibleRides().map(r=>[r.id,r.pickup,r.destination,r.mode,r.fare,r.status])].map(row=>row.map(safe).join(',')).join('\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.href=url;a.download='raahi-rides.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}if(['accept','reject','arrive','start','complete','cancel'].includes(action))return transition(id,action);if(action==='review'){const c=captains.find(x=>x.id===id);return modal(`<h2>${esc(c.name)}</h2><p>${esc(c.vehicle||'Vehicle details pending')}</p><p>${c.approved?'Approved account':'Awaiting manual review'}</p><div class="notice">${live?'This build does not collect or verify identity documents. Review the applicant through your verified KYC process before approving.':'Sample application for interface testing. No real documents.'}</div>`)}if(action==='approve'||action==='rejectCaptain'){const approved=action==='approve';let reason=approved?'Approved by operations':prompt('Reason for rejection / suspension');if(reason===null)return;if(!approved&&reason.trim().length<3)throw Error('Enter a reason with at least 3 characters');if(live)await api('approve',{p_captain_id:id,p_approved:approved,p_reason:reason});else{const c=demo.captains.find(x=>x.id===id);c.approved=approved;if(!approved)c.online=false;log(approved?'captain.approved':'captain.rejected',id,reason)}await load();render();toast(approved?'Captain approved':'Captain suspended / rejected');return}if(action==='online'){const me=live?profile:demo.captains[0];if(!me?.approved)throw Error('Approval required before going online');if(live)await api('availability',{p_online:!me.online});else{me.online=!me.online;save()}await load();render();return}if(action==='location'){if(!live){toast('Simulation location is illustrated on the map.');return}if(!navigator.geolocation)throw Error('Geolocation is unavailable');const pos=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:12000,maximumAge:10000}));await api('location',{p_lat:pos.coords.latitude,p_lng:pos.coords.longitude});toast('Current position shared once for your assigned trip.');return}if(action==='track'){if(!live){toast('Simulation map shows illustrative positions.');return}const p=await api('tracking',{p_ride_id:id});if(p?.lat==null||p?.lng==null)throw Error('Captain has not shared a position yet');const lat=Number(p.lat),lng=Number(p.lng);if(!Number.isFinite(lat)||!Number.isFinite(lng))throw Error('Position unavailable');modal('<h2>Captain position</h2><p>'+esc(p.name)+' · '+esc(p.vehicle)+'</p><iframe title="Captain map" style="border:0;width:100%;height:320px" src="https://www.openstreetmap.org/export/embed.html?bbox='+[lng-.015,lat-.015,lng+.015,lat+.015].join('%2C')+'&layer=mapnik&marker='+lat+'%2C'+lng+'"></iframe><p class="fineprint">Last shared: '+esc(p.updated_at)+' · refresh by reopening this view.</p>');return}if(action==='sos'){if(live)await api('sos',{p_ride_id:id});else log('safety.sos',id,'Demo alert');close();toast('Alert recorded. No emergency call or SMS has been sent.');return}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-tab],[data-action],[data-mode],[data-filter]');if(!el)return;try{if(el.dataset.tab){tab=el.dataset.tab;render()}else if(el.dataset.mode){mode=el.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('active',x.dataset.mode===mode))}else if(el.dataset.filter){filter=el.dataset.filter;render()}else{if(busy)return;busy=true;el.disabled=true;await act(el.dataset.action,el.dataset.id)}}catch(err){toast(err.message)}finally{busy=false;el.disabled=false}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});
document.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;busy=true;const button=e.submitter;if(button)button.disabled=true;try{const f=new FormData(e.target);if(e.target.id==='booking'){if(live&&!session)throw Error('Sign in before requesting a ride');if(visibleRides().some(x=>!['completed','cancelled'].includes(x.status)))throw Error('Complete or cancel your current ride first');const a=places[f.get('pickup')],b=places[f.get('drop')];if(live)await api('book',{p_pickup:a[0],p_destination:b[0],p_pickup_lat:a[1],p_pickup_lng:a[2],p_drop_lat:b[1],p_drop_lng:b[2],p_mode:mode,p_request_key:sessionStorage.getItem('raahi.bookingKey')||(sessionStorage.setItem('raahi.bookingKey',uid()),sessionStorage.getItem('raahi.bookingKey'))});else{const km=estimate(a,b),fare=Math.ceil(({bike:20,auto:35,cab:60}[mode])+km*({bike:8,auto:13,cab:19}[mode]));const r={id:uid(),customer_id:'customer-demo',pickup:a[0],destination:b[0],mode,fare,distance_km:km,status:'requested',code:String(Math.floor(1000+Math.random()*9000)),created_at:now()};demo.rides.unshift(r);log('ride.created',r.id)}sessionStorage.removeItem('raahi.bookingKey');await load();render();toast('Ride requested. Open the Captain panel to accept.')}else if(e.target.id==='auth'){if(!C.supabaseUrl||!C.supabaseAnonKey)throw Error('Configure Supabase in config.js first');const signup=button?.value==='signup';const res=await fetch(C.supabaseUrl+'/auth/v1/'+(signup?'signup':'token?grant_type=password'),{method:'POST',headers:{apikey:C.supabaseAnonKey,'Content-Type':'application/json'},body:JSON.stringify({email:f.get('email'),password:f.get('password'),...(signup?{data:{name:f.get('name'),role:portal}}:{})})});const data=await res.json();if(!res.ok)throw Error(data.msg||data.error_description||data.message||'Sign in failed');if(data.access_token){session=data;sessionStorage.setItem('raahi.session',JSON.stringify(data));live=true;localStorage.setItem('raahi.mode','live');close();await load();render()}else toast('Account created. Confirm your email, then sign in.')}}catch(err){toast(err.message)}finally{busy=false;if(button)button.disabled=false}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});window.addEventListener('storage',async()=>{try{demo=JSON.parse(localStorage.getItem('raahi.demo'))||seed();await load();render()}catch{}});
async function refresh(){if(busy||$('#overlay').children.length||document.activeElement?.tagName==='INPUT'||document.activeElement?.tagName==='SELECT')return;try{const a=$('#pickup')?.value,b=$('#drop')?.value;await load();render();if(a&&$('#pickup'))$('#pickup').value=a;if(b&&$('#drop'))$('#drop').value=b}catch(e){toast(e.message)}}
load().then(render).catch(e=>{render();toast(e.message)});setInterval(()=>{if(live&&session&&!document.hidden)refresh()},5000);
})();
